private static void buildTable() {
    table = new AdjGraph();
    for(int i = 0; i < numberOfNodes; i ++) {
        table.addVertex(new VertexNode(i));
    }
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader("data.txt"));
        String line = null;
        String[] temp = null;
        int[] edge = new int[2];
        while((line = reader.readLine()) != null) {
            temp = line.split(",");
            edge[0] = Integer.parseInt(temp[0]);
            edge[1] = Integer.parseInt(temp[1]);
            if(table.getVertex(edge[0]).getFirstEdge() == null) {
                table.getVertex(edge[0]).setFirstEdge(new EdgeNode(edge[1]));
            } else {
                EdgeNode tempEdge = table.getVertex(edge[0]).getFirstEdge();
                while(tempEdge.getNext() != null) {
                    tempEdge = tempEdge.getNext();
                }
                tempEdge.setNext(new EdgeNode(edge[1]));
            }
            if(table.getVertex(edge[1]).getFirstEdge() == null) {
                table.getVertex(edge[1]).setFirstEdge(new EdgeNode(edge[0]));
            } else {
                EdgeNode tempEdge = table.getVertex(edge[1]).getFirstEdge();
                while(tempEdge.getNext() != null) {
                    tempEdge = tempEdge.getNext();
                }
                tempEdge.setNext(new EdgeNode(edge[0]));
            }
        }
    } catch (Exception e) {
        System.out.println("读取文件错误！请检查文件！");
        e.printStackTrace();
    } finally {
        if(reader != null) {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
    System.out.println("邻接表建立完成！邻接表如下：");
    showTable();
}

private static void convertStructure() {
    System.out.println("1. 邻接矩阵转邻接表");
    System.out.println("2. 邻接表转邻接矩阵");
    System.out.print("请输入选择：");
    int choice = scanner.nextInt();
    switch(choice) {
        case 1:
            convertToTable();
            break;
        case 2:
            convertToMatrix();
            break;
        default:
            System.out.println("选择有误！");
            break;
    }
}

private static void convertToTable() {
    if(matrix == null) {
        System.out.println("暂无邻接矩阵数据！");
        return;
    }
    table = new AdjGraph();
    for(int i = 0; i < numberOfNodes; i ++) {
        table.addVertex(new VertexNode(i));
    }
    for(int i = 0; i < numberOfNodes; i ++) {
        for(int j = i; j < numberOfNodes; j ++) {
            if(matrix[i][j] == 1) {
                if(table.getVertex(i).getFirstEdge() == null) {
                    table.getVertex(i).setFirstEdge(new EdgeNode(j));
                } else {
                    EdgeNode tempEdge = table.getVertex(i).getFirstEdge();
                    while(tempEdge.getNext() != null) {
                        tempEdge = tempEdge.getNext();
                    }
                    tempEdge.setNext(new EdgeNode(j));
                }
                if(table.getVertex(j).getFirstEdge() == null) {
                    table.getVertex(j).setFirstEdge(new EdgeNode(i));
                } else {
                    EdgeNode tempEdge = table.getVertex(j).getFirstEdge();
                    while(tempEdge.getNext() != null) {
                        tempEdge = tempEdge.getNext();
                    }
                    tempEdge.setNext(new EdgeNode(i));
                }
            }
        }
    }
    System.out.println("转换完成！");
    showTable();
}

private static void convertToMatrix() {
    if(table == null) {
        System.out.println("暂无邻接表数据！");
        return;
    }
    matrix = new int[numberOfNodes][numberOfNodes];
    for(int i = 0; i < numberOfNodes; i ++) {
        VertexNode tempVertex = table.getVertex(i);
        EdgeNode tempEdge = tempVertex.getFirstEdge();
        while(tempEdge != null) {
            matrix[i][tempEdge.getAdjvex()] = 1;
            matrix[tempEdge.getAdjvex()][i] = 1;
            tempEdge = tempEdge.getNext();
        }
    }
    System.out.println("转换完成！");
    showMatrix();
}

